<template><main class="page"><section class="hero"><div class="wrap"><div class="kicker">UMS MACHINERY SPECIFICATION LIBRARY</div><div class="crumb"><NuxtLink to="/spec-library">Spec Library</NuxtLink> / <NuxtLink to="/spec-library/engine-lathes">Engine Lathes, Mills & Drills</NuxtLink> / {{ maker?.name }}</div><h1>{{ maker?.name }} Engine Lathe, Mill & Drill Specifications</h1><p>Browse historical {{ maker?.name }} conventional machine records by model and recorded configuration.</p></div></section><section class="wrap section" v-if="maker"><h2>{{ maker.name }} Models</h2><div class="grid"><NuxtLink v-for="m in maker.models" :key="m.slug" :to="'/spec-library/'+maker.slug+'/engine-lathes/'+m.slug" class="card"><strong>{{m.name}}</strong><span>{{m.records}} historical record{{m.records===1?'':'s'}}</span></NuxtLink></div></section><section v-else class="wrap section"><h2>Manufacturer not found</h2><NuxtLink to="/spec-library/engine-lathes">Return to library</NuxtLink></section></main></template>
<script setup>
import a from '~/assets/data/engine-library-a-c.js';import d from '~/assets/data/engine-library-d-h.js';import i from '~/assets/data/engine-library-i-m.js';import n from '~/assets/data/engine-library-n-r.js';import s from '~/assets/data/engine-library-s-t.js';import u from '~/assets/data/engine-library-u-z.js';import {mergeSpecLibrary} from '~/utils/mergeSpecLibrary'
const route=useRoute(),rawLibrary=mergeSpecLibrary([a,d,i,n,s,u]);const hasUsefulSpecs=v=>(v?.[2]||[]).some(x=>x?.[0] && x[0] !== 'Machine Type' && x[0] !== 'Advertising Summary' && x?.[1]);const cleanModel=m=>({...m,years:(m.years||[]).filter(hasUsefulSpecs)});const library=rawLibrary.map(m=>({...m,models:(m.models||[]).map(cleanModel).filter(x=>x.years.length)})).filter(m=>m.models.length);const maker=computed(()=>library.find(x=>x.slug===route.params.manufacturer));useSeoMeta({title:()=>maker.value?`${maker.value.name} Machine Specifications | UMS Spec Library`:'Machine Specifications | UMS',description:()=>maker.value?`Historical ${maker.value.name} engine lathe, manual mill, drilling and conventional machine specifications.`:'Historical machine specifications.'})
</script><style scoped>.page{color:#17273a}.wrap{max-width:1200px;margin:auto;padding:0 28px}.hero{background:#0b2545;color:#fff;padding:42px 0;border-bottom:4px solid #f47b20}.kicker{font-size:.78rem;font-weight:900;letter-spacing:.12em;color:#f47b20;margin-bottom:10px}.crumb,.crumb a{color:#c9d8e8}.hero h1{font-size:clamp(2rem,4vw,3rem)}.section{padding:40px 28px 80px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.card{display:flex;flex-direction:column;padding:15px;border:1px solid #d7e0e8;border-radius:7px;text-decoration:none;color:#17273a}.card strong{color:#0b2545}.card span{color:#68798a;font-size:.88rem;margin-top:5px}@media(max-width:800px){.grid{grid-template-columns:1fr}}</style>